import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
for k in G: print(k, len(G[k]), len(G[k][0]))

from collections import Counter, deque
def analyze(inp,out):
    h,w=len(inp),len(inp[0]); bg=Counter(x for r in inp for x in r).most_common(1)[0][0]
    # find shape components (single color != bg), get bboxes, interior cells
    seen=[[False]*w for _ in range(h)]
    comps=[]
    for i in range(h):
        for j in range(w):
            if not seen[i][j] and inp[i][j]!=bg:
                c=inp[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and inp[ny][nx]==c:
                            seen[ny][nx]=True; st.append((ny,nx))
                comps.append((c,cells))
    print('bg',bg)
    for c,cells in comps:
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        bh,bw=max(ys)-min(ys)+1,max(xs)-min(xs)+1
        # interior: flood from border over non-c cells
        wall=(lambda y,x: inp[y][x]==c)
        reach=[[False]*w for _ in range(h)]; dq=deque()
        for i in range(h):
            for j in (0,w-1):
                if not wall(i,j) and not reach[i][j]: reach[i][j]=True; dq.append((i,j))
        for j in range(w):
            for i in (0,h-1):
                if not wall(i,j) and not reach[i][j]: reach[i][j]=True; dq.append((i,j))
        while dq:
            y,x=dq.popleft()
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<h and 0<=nx<w and not reach[ny][nx] and not wall(ny,nx):
                    reach[ny][nx]=True; dq.append((ny,nx))
        inter=[(y,x) for y in range(h) for x in range(w) if not reach[y][x] and not wall(y,x)]
        # what fill was applied
        fills=Counter(out[y][x] for y,x in inter)
        print(f'color {c} bbox {bh}x{bw} area {bh*bw} interior {len(inter)} fills {dict(fills)}')
for k in ['Demo pair 1','Demo pair 2']:
    print('==',k); analyze(G[k+' input'],G[k+' output'])

