os.makedirs('programs',exist_ok=True)
prog='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for r in grid for x in r).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    comps = []
    for i in range(h):
        for j in range(w):
            if not seen[i][j] and grid[i][j] != bg:
                c = grid[i][j]; st = [(i, j)]; seen[i][j] = True; cells = []
                while st:
                    y, x = st.pop(); cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == c:
                            seen[ny][nx] = True; st.append((ny, nx))
                comps.append((c, cells))
    for c, cells in comps:
        wall = lambda y, x: grid[y][x] == c
        reach = [[False] * w for _ in range(h)]; dq = deque()
        for i in range(h):
            for j in (0, w-1):
                if not wall(i, j) and not reach[i][j]: reach[i][j] = True; dq.append((i, j))
        for j in range(w):
            for i in (0, h-1):
                if not wall(i, j) and not reach[i][j]: reach[i][j] = True; dq.append((i, j))
        while dq:
            y, x = dq.popleft()
            for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny, nx = y+dy, x+dx
                if 0 <= ny < h and 0 <= nx < w and not reach[ny][nx] and not wall(ny, nx):
                    reach[ny][nx] = True; dq.append((ny, nx))
        ys = [p[0] for p in cells]; xs = [p[1] for p in cells]
        area = (max(ys)-min(ys)+1) * (max(xs)-min(xs)+1)
        fill = 7 if area % 2 else 2
        for y in range(h):
            for x in range(w):
                if not reach[y][x] and not wall(y, x):
                    out[y][x] = fill
    return out
'''
